TypeScript (async iterator)
import { CallAdapter } from '@redwood/sdk'
import Ajv from 'ajv'

const adapter = new CallAdapter()
const schema = { type: 'object', properties: { text: { type: 'string' } }, required: ['text'] }
const fn = adapter.registerFunction('summarize', { schema, idempotent: false })

for await (const chunk of fn.callStream({ text: '...' })) {
  console.log('chunk', chunk)
}

const res = await fn.call({ text: 'short' })
console.log('validated result', res)

Go (channel reader)
adapter := sdk.NewCallAdapter()
schema := `{"type":"object","properties":{"text":{"type":"string"}},"required":["text"]}`
fn := adapter.RegisterFunction("summarize", schema, sdk.FunctionOptions{Idempotent: false})
ch := fn.CallStream(ctx, map[string]interface{}{"text":"hello"})
for part := range ch {
    if part.Error != nil { 
        log.Printf("stream error: %v", part.Error)
        break
    }
    fmt.Println("part:", string(part.Bytes))
}
// final parsed object available as fn.Call(ctx, args) returning typed struct or validation error
